require dirname(__DIR__).'/bootstrap.php';require_admin();$adminTitle='Bot lọc bình luận';
if(isset($_GET['delete'])){db()->prepare('DELETE FROM moderation_terms WHERE id=?')->execute([(int)$_GET['delete']]);header('Location: moderation.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$term=mb_strtolower(trim($_POST['term']??''),'UTF-8');$weight=max(1,min(10,(int)($_POST['weight']??2)));if($term!=='')db()->prepare("INSERT INTO moderation_terms(term,category,weight,source,active) VALUES(?,?,?,?,1) ON DUPLICATE KEY UPDATE weight=VALUES(weight),source='admin',active=1")->execute([$term,'negative',$weight,'admin']);header('Location: moderation.php');exit;}
$terms=db()->query('SELECT * FROM moderation_terms ORDER BY source DESC,CHAR_LENGTH(term) DESC,term ASC')->fetchAll();$flagged=(int)db()->query("SELECT COUNT(*) FROM comments WHERE moderation_status='hidden'")->fetchColumn();$muted=(int)db()->query("SELECT COUNT(*) FROM comment_bans WHERE permanent=1 OR ends_at>NOW()")->fetchColumn();require __DIR__.'/_header.php'; ?>
